export type InputSize = "sm" | "md" | "lg" | "xl" | "2xl";

/** The whole look of an Input as Tailwind classes. The border and fill live on the wrapper. */
const base = "rx-control rx-field flex w-full items-center [--_icon:16px]";

// Padding is one pixel less than Figma because the 1px edge is a real border. Pill pads more.
const sizes: Record<InputSize, { box: string; px: string; pillPx: string }> = {
	sm: { box: "h-7 gap-2 text-[13px]/5", px: "px-[9px]", pillPx: "px-[11px]" },
	md: { box: "h-8 gap-2 text-[13px]/5", px: "px-[9px]", pillPx: "px-[11px]" },
	lg: { box: "h-9 gap-2 text-sm/5", px: "px-[11px]", pillPx: "px-[15px]" },
	xl: { box: "h-11 gap-2 text-sm/5", px: "px-[15px]", pillPx: "px-[19px]" },
	"2xl": { box: "h-12 gap-2.5 text-sm/5 [--_icon:20px]", px: "px-[15px]", pillPx: "px-[19px]" },
};

type InputStyle = { size?: InputSize; pill?: boolean };

export function inputClass({ size = "md", pill }: InputStyle = {}) {
	const { box, px, pillPx } = sizes[size];
	return `${base} ${box} ${pill ? `${pillPx} rounded-full` : `${px} rounded-(--radius-control)`}`;
}

/** Classes for the parts inside an Input. */
export const inputParts = {
	field:
		"min-w-0 flex-1 bg-transparent outline-none placeholder:text-(--subtle-foreground) disabled:placeholder:text-(--disabled-foreground)",
	icon: "inline-flex size-(--_icon) shrink-0 text-(--subtle-foreground) [&>svg]:size-full",
};

"use client";

import { type InputHTMLAttributes, type ReactNode, type Ref, useContext, useRef } from "react";
import { FieldContext } from "./field-context";
import { cn } from "@/lib/utils";
import { type InputSize, inputClass, inputParts } from "./input.styles";

export type InputProps = Omit<InputHTMLAttributes<HTMLInputElement>, "size"> & {
	/** Control height: 28, 32, 36, 44 and 48. */
	size?: InputSize;
	/** A fully rounded field, for search bars. Independent of the radius mode. */
	pill?: boolean;
	leadingIcon?: ReactNode;
	trailingIcon?: ReactNode;
	ref?: Ref<HTMLInputElement>;
};

/**
 * A native `<input>` inside a wrapper that draws the field. Put it in a `Field` to get a label, a
 * hint and an error wired up, or give it an `aria-label`. `aria-invalid` turns the edge red.
 */
export function Input({
	size,
	pill,
	leadingIcon,
	trailingIcon,
	className,
	ref,
	...rest
}: InputProps) {
	const inner = useRef<HTMLInputElement>(null);
	const fieldState = useContext(FieldContext);
	const { field, icon } = inputParts;

	return (
		// The wrapper only forwards pointer focus; keyboard users already land on the input.
		// oxlint-disable-next-line jsx-a11y/no-static-element-interactions
		<div
			className={cn(inputClass({ size, pill }), className)}
			onPointerDown={(event) => {
				if (event.target instanceof Element && event.target.closest("input, button, a")) return;
				event.preventDefault();
				inner.current?.focus();
			}}
		>
			{leadingIcon && <span className={icon}>{leadingIcon}</span>}
			<input
				id={fieldState?.id}
				aria-describedby={fieldState?.describedBy}
				aria-invalid={fieldState?.invalid || undefined}
				{...rest}
				ref={(node) => {
					inner.current = node;
					if (typeof ref === "function") ref(node);
					else if (ref) ref.current = node;
				}}
				className={field}
			/>
			{trailingIcon && <span className={icon}>{trailingIcon}</span>}
		</div>
	);
}
